contracts/AETHToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";

/**
 * @title AETHToken
 * @dev Aetherium Proxy native token with staking functionality
 */
contract AETHToken is ERC20, ERC20Burnable, Ownable {
    uint256 public constant INITIAL_SUPPLY = 1_000_000_000 * 10**18; // 1 billion tokens
    uint256 public constant STAKING_APY = 10; // 10% APY
    uint256 public constant SECONDS_PER_YEAR = 365 days;

    struct StakeInfo {
        uint256 amount;
        uint256 startTime;
        uint256 lastClaimTime;
    }

    mapping(address => StakeInfo) public stakes;
    uint256 public totalStaked;

    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 amount);

    constructor() ERC20("Aetherium Token", "AETH") Ownable(msg.sender) {
        _mint(msg.sender, INITIAL_SUPPLY);
    }

    /**
     * @dev Stake tokens to earn rewards
     */
    function stake(uint256 amount) external {
        require(amount > 0, "Cannot stake 0 tokens");
        require(balanceOf(msg.sender) >= amount, "Insufficient balance");

        // Claim any pending rewards first
        if (stakes[msg.sender].amount > 0) {
            _claimRewards(msg.sender);
        }

        _transfer(msg.sender, address(this), amount);

        stakes[msg.sender].amount += amount;
        stakes[msg.sender].startTime = block.timestamp;
        stakes[msg.sender].lastClaimTime = block.timestamp;
        totalStaked += amount;

        emit Staked(msg.sender, amount);
    }

    /**
     * @dev Unstake tokens
     */
    function unstake(uint256 amount) external {
        require(amount > 0, "Cannot unstake 0 tokens");
        require(stakes[msg.sender].amount >= amount, "Insufficient staked amount");

        // Claim rewards before unstaking
        _claimRewards(msg.sender);

        stakes[msg.sender].amount -= amount;
        totalStaked -= amount;

        _transfer(address(this), msg.sender, amount);

        emit Unstaked(msg.sender, amount);
    }

    /**
     * @dev Claim staking rewards
     */
    function claimRewards() external {
        require(stakes[msg.sender].amount > 0, "No active stake");
        _claimRewards(msg.sender);
    }

    /**
     * @dev Internal function to calculate and distribute rewards
     */
    function _claimRewards(address user) internal {
        uint256 reward = calculateRewards(user);
        if (reward > 0) {
            stakes[user].lastClaimTime = block.timestamp;
            _mint(user, reward);
            emit RewardsClaimed(user, reward);
        }
    }

    /**
     * @dev Calculate pending rewards for a user
     */
    function calculateRewards(address user) public view returns (uint256) {
        StakeInfo memory stakeInfo = stakes[user];
        if (stakeInfo.amount == 0) return 0;

        uint256 timeStaked = block.timestamp - stakeInfo.lastClaimTime;
        uint256 reward = (stakeInfo.amount * STAKING_APY * timeStaked) / (100 * SECONDS_PER_YEAR);
        return reward;
    }

    /**
     * @dev Get staking info for a user
     */
    function getStakeInfo(address user) external view returns (uint256 amount, uint256 startTime, uint256 pendingRewards) {
        StakeInfo memory stakeInfo = stakes[user];
        return (stakeInfo.amount, stakeInfo.startTime, calculateRewards(user));
    }

    /**
     * @dev Mint new tokens (only owner)
     */
    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }
}

contracts/AETHTokenV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";

/**
 * @title AETHTokenV2
 * @dev Enhanced Aetherium Token with burn mechanism for VPN access, advanced staking, and vesting
 */
contract AETHTokenV2 is ERC20, ERC20Burnable, Ownable {
    uint256 public constant INITIAL_SUPPLY = 1_000_000_000 * 10**18; // 1 billion tokens
    uint256 public constant SECONDS_PER_YEAR = 365 days;
    uint256 public constant MIN_STAKE_AMOUNT = 100 * 10**18; // 100 AETH minimum

    // Burn rates for VPN access (per minute)
    uint256 public burnRatePerMinute = 0.001 ether; // 0.001 AETH per minute

    // Staking tiers with different APY
    uint256 public constant TIER1_APY = 50; // 50% APY for 6+ months lock
    uint256 public constant TIER2_APY = 75; // 75% APY for 12+ months lock
    uint256 public constant TIER3_APY = 100; // 100% APY for 24+ months lock

    struct StakeInfo {
        uint256 amount;
        uint256 startTime;
        uint256 lockUntil; // Timestamp when unlock is available
        uint256 lastClaimTime;
        uint8 tier; // 1, 2, or 3
    }

    struct VestingSchedule {
        uint256 totalAmount;
        uint256 releasedAmount;
        uint256 startTime;
        uint256 duration;
    }

    mapping(address => StakeInfo) public stakes;
    mapping(address => VestingSchedule) public vestingSchedules;
    mapping(address => uint256) public totalBurned; // Track burned amount per user

    uint256 public totalStaked;
    uint256 public totalBurnedGlobal;
    uint256 public transactionFeePercent = 5; // 5% fee on transfers
    address public feeCollector;

    event Staked(address indexed user, uint256 amount, uint8 tier, uint256 lockUntil);
    event Unstaked(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 amount);
    event BurnedForAccess(address indexed user, uint256 amount, uint256 durationMinutes);
    event VestingCreated(address indexed user, uint256 amount, uint256 duration);
    event VestingReleased(address indexed user, uint256 amount);
    event FeeCollected(address indexed from, address indexed to, uint256 amount);

    constructor(address _feeCollector) ERC20("Aetherium Token", "AETH") Ownable(msg.sender) {
        _mint(msg.sender, INITIAL_SUPPLY);
        feeCollector = _feeCollector;
    }

    /**
     * @dev Burn tokens to get VPN access
     * @param durationMinutes Number of minutes of VPN access
     */
    function burnForAccess(uint256 durationMinutes) external {
        require(durationMinutes > 0, "Minutes must be > 0");
        uint256 burnAmount = durationMinutes * burnRatePerMinute;
        require(balanceOf(msg.sender) >= burnAmount, "Insufficient balance");

        _burn(msg.sender, burnAmount);
        totalBurned[msg.sender] += burnAmount;
        totalBurnedGlobal += burnAmount;

        emit BurnedForAccess(msg.sender, burnAmount, durationMinutes);
    }

    /**
     * @dev Stake tokens with lock period
     * @param amount Amount to stake
     * @param lockMonths Lock period in months (6, 12, or 24)
     */
    function stakeWithLock(uint256 amount, uint256 lockMonths) external {
        require(amount >= MIN_STAKE_AMOUNT, "Amount below minimum");
        require(lockMonths == 6 || lockMonths == 12 || lockMonths == 24, "Invalid lock period");
        require(balanceOf(msg.sender) >= amount, "Insufficient balance");

        // Claim any pending rewards first
        if (stakes[msg.sender].amount > 0) {
            _claimRewards(msg.sender);
        }

        _transfer(msg.sender, address(this), amount);

        uint8 tier;
        if (lockMonths == 6) tier = 1;
        else if (lockMonths == 12) tier = 2;
        else tier = 3;

        uint256 lockUntil = block.timestamp + (lockMonths * 30 days);

        stakes[msg.sender].amount += amount;
        stakes[msg.sender].startTime = block.timestamp;
        stakes[msg.sender].lockUntil = lockUntil;
        stakes[msg.sender].lastClaimTime = block.timestamp;
        stakes[msg.sender].tier = tier;
        totalStaked += amount;

        emit Staked(msg.sender, amount, tier, lockUntil);
    }

    /**
     * @dev Unstake tokens (only after lock period)
     */
    function unstake(uint256 amount) external {
        require(amount > 0, "Cannot unstake 0");
        require(stakes[msg.sender].amount >= amount, "Insufficient staked amount");
        require(block.timestamp >= stakes[msg.sender].lockUntil, "Still locked");

        // Claim rewards before unstaking
        _claimRewards(msg.sender);

        stakes[msg.sender].amount -= amount;
        totalStaked -= amount;

        _transfer(address(this), msg.sender, amount);

        emit Unstaked(msg.sender, amount);
    }

    /**
     * @dev Claim staking rewards
     */
    function claimRewards() external {
        require(stakes[msg.sender].amount > 0, "No active stake");
        _claimRewards(msg.sender);
    }

    /**
     * @dev Internal function to calculate and distribute rewards
     */
    function _claimRewards(address user) internal {
        uint256 reward = calculateRewards(user);
        if (reward > 0) {
            stakes[user].lastClaimTime = block.timestamp;
            _mint(user, reward);
            emit RewardsClaimed(user, reward);
        }
    }

    /**
     * @dev Calculate pending rewards based on tier
     */
    function calculateRewards(address user) public view returns (uint256) {
        StakeInfo memory stakeInfo = stakes[user];
        if (stakeInfo.amount == 0) return 0;

        uint256 apy;
        if (stakeInfo.tier == 1) apy = TIER1_APY;
        else if (stakeInfo.tier == 2) apy = TIER2_APY;
        else apy = TIER3_APY;

        uint256 timeStaked = block.timestamp - stakeInfo.lastClaimTime;
        uint256 reward = (stakeInfo.amount * apy * timeStaked) / (100 * SECONDS_PER_YEAR);
        return reward;
    }

    /**
     * @dev Create vesting schedule (for team/advisors)
     */
    function createVesting(address beneficiary, uint256 amount, uint256 durationMonths) external onlyOwner {
        require(vestingSchedules[beneficiary].totalAmount == 0, "Vesting already exists");
        require(amount > 0, "Amount must be > 0");

        vestingSchedules[beneficiary] = VestingSchedule({
            totalAmount: amount,
            releasedAmount: 0,
            startTime: block.timestamp,
            duration: durationMonths * 30 days
        });

        _transfer(msg.sender, address(this), amount);
        emit VestingCreated(beneficiary, amount, durationMonths);
    }

    /**
     * @dev Release vested tokens
     */
    function releaseVesting() external {
        VestingSchedule storage vesting = vestingSchedules[msg.sender];
        require(vesting.totalAmount > 0, "No vesting schedule");

        uint256 releasable = calculateReleasableAmount(msg.sender);
        require(releasable > 0, "No tokens to release");

        vesting.releasedAmount += releasable;
        _transfer(address(this), msg.sender, releasable);

        emit VestingReleased(msg.sender, releasable);
    }

    /**
     * @dev Calculate releasable vested amount
     */
    function calculateReleasableAmount(address beneficiary) public view returns (uint256) {
        VestingSchedule memory vesting = vestingSchedules[beneficiary];
        if (vesting.totalAmount == 0) return 0;

        uint256 elapsed = block.timestamp - vesting.startTime;
        if (elapsed >= vesting.duration) {
            return vesting.totalAmount - vesting.releasedAmount;
        }

        uint256 vested = (vesting.totalAmount * elapsed) / vesting.duration;
        return vested - vesting.releasedAmount;
    }

    /**
     * @dev Override transfer to collect 5% fee
     */
    function transfer(address to, uint256 amount) public virtual override returns (bool) {
        address from = msg.sender;

        // Skip fee for staking/unstaking operations
        if (to == address(this) || from == address(this)) {
            return super.transfer(to, amount);
        }

        uint256 fee = (amount * transactionFeePercent) / 100;
        uint256 amountAfterFee = amount - fee;

        _transfer(from, to, amountAfterFee);
        _transfer(from, feeCollector, fee);

        emit FeeCollected(from, to, fee);
        return true;
    }

    /**
     * @dev Get complete stake info
     */
    function getStakeInfo(address user) external view returns (
        uint256 amount,
        uint256 startTime,
        uint256 lockUntil,
        uint256 pendingRewards,
        uint8 tier,
        bool isLocked
    ) {
        StakeInfo memory stakeInfo = stakes[user];
        return (
            stakeInfo.amount,
            stakeInfo.startTime,
            stakeInfo.lockUntil,
            calculateRewards(user),
            stakeInfo.tier,
            block.timestamp < stakeInfo.lockUntil
        );
    }

    /**
     * @dev Update burn rate (owner only)
     */
    function setBurnRate(uint256 newRate) external onlyOwner {
        burnRatePerMinute = newRate;
    }

    /**
     * @dev Update transaction fee (owner only)
     */
    function setTransactionFee(uint256 newFee) external onlyOwner {
        require(newFee <= 10, "Fee too high");
        transactionFeePercent = newFee;
    }

    /**
     * @dev Update fee collector (owner only)
     */
    function setFeeCollector(address newCollector) external onlyOwner {
        feeCollector = newCollector;
    }

    /**
     * @dev Get user statistics
     */
    function getUserStats(address user) external view returns (
        uint256 balance,
        uint256 stakedAmount,
        uint256 pendingRewards,
        uint256 burnedAmount,
        uint256 vestedAmount,
        uint256 releasableVested
    ) {
        return (
            balanceOf(user),
            stakes[user].amount,
            calculateRewards(user),
            totalBurned[user],
            vestingSchedules[user].totalAmount,
            calculateReleasableAmount(user)
        );
    }

    /**
     * @dev Mint new tokens (only owner - for rewards)
     */
    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }
}

contracts/MinerNode.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./AETHToken.sol";

/**
 * @title MinerNode
 * @dev Manage VPN miner nodes and their rewards
 */
contract MinerNode is Ownable {
    AETHToken public aethToken;

    struct Node {
        address owner;
        string location;
        uint256 bandwidthMbps;
        uint256 registeredAt;
        bool isActive;
        uint256 totalDataShared; // in MB
        uint256 totalEarnings;
        uint256 reputation; // 0-100 score
    }

    mapping(bytes32 => Node) public nodes; // nodeId => Node
    mapping(address => bytes32[]) public ownerNodes; // owner => nodeIds
    bytes32[] public allNodeIds;

    uint256 public constant MIN_BANDWIDTH = 10; // 10 Mbps minimum
    uint256 public constant REWARD_PER_GB = 1 * 10**18; // 1 AETH per GB
    uint256 public constant MIN_REPUTATION = 50;

    event NodeRegistered(bytes32 indexed nodeId, address indexed owner, string location);
    event NodeDeactivated(bytes32 indexed nodeId);
    event DataShared(bytes32 indexed nodeId, uint256 dataMB, uint256 reward);
    event ReputationUpdated(bytes32 indexed nodeId, uint256 newReputation);

    constructor(address _aethToken) Ownable(msg.sender) {
        aethToken = AETHToken(_aethToken);
    }

    /**
     * @dev Register a new miner node
     */
    function registerNode(string memory location, uint256 bandwidthMbps) external returns (bytes32) {
        require(bandwidthMbps >= MIN_BANDWIDTH, "Bandwidth too low");

        bytes32 nodeId = keccak256(abi.encodePacked(msg.sender, block.timestamp, allNodeIds.length));

        nodes[nodeId] = Node({
            owner: msg.sender,
            location: location,
            bandwidthMbps: bandwidthMbps,
            registeredAt: block.timestamp,
            isActive: true,
            totalDataShared: 0,
            totalEarnings: 0,
            reputation: 100 // Start with perfect reputation
        });

        ownerNodes[msg.sender].push(nodeId);
        allNodeIds.push(nodeId);

        emit NodeRegistered(nodeId, msg.sender, location);
        return nodeId;
    }

    /**
     * @dev Record data shared by a node and distribute rewards
     */
    function recordDataShared(bytes32 nodeId, uint256 dataMB) external onlyOwner {
        require(nodes[nodeId].isActive, "Node not active");
        require(dataMB > 0, "Data must be greater than 0");

        Node storage node = nodes[nodeId];
        node.totalDataShared += dataMB;

        // Calculate reward: 1 AETH per GB
        uint256 reward = (dataMB * REWARD_PER_GB) / 1000;
        node.totalEarnings += reward;

        // Mint rewards to node owner
        aethToken.mint(node.owner, reward);

        emit DataShared(nodeId, dataMB, reward);
    }

    /**
     * @dev Update node reputation (based on uptime, quality, etc.)
     */
    function updateReputation(bytes32 nodeId, uint256 newReputation) external onlyOwner {
        require(nodes[nodeId].owner != address(0), "Node does not exist");
        require(newReputation <= 100, "Reputation must be 0-100");

        nodes[nodeId].reputation = newReputation;

        // Deactivate if reputation too low
        if (newReputation < MIN_REPUTATION) {
            nodes[nodeId].isActive = false;
            emit NodeDeactivated(nodeId);
        }

        emit ReputationUpdated(nodeId, newReputation);
    }

    /**
     * @dev Deactivate a node
     */
    function deactivateNode(bytes32 nodeId) external {
        require(nodes[nodeId].owner == msg.sender || msg.sender == owner(), "Not authorized");
        nodes[nodeId].isActive = false;
        emit NodeDeactivated(nodeId);
    }

    /**
     * @dev Get all nodes owned by an address
     */
    function getOwnerNodes(address owner) external view returns (bytes32[] memory) {
        return ownerNodes[owner];
    }

    /**
     * @dev Get active nodes by location
     */
    function getActiveNodesByLocation(string memory location) external view returns (bytes32[] memory) {
        uint256 count = 0;

        // Count matching nodes
        for (uint256 i = 0; i < allNodeIds.length; i++) {
            Node memory node = nodes[allNodeIds[i]];
            if (node.isActive && keccak256(bytes(node.location)) == keccak256(bytes(location))) {
                count++;
            }
        }

        // Create result array
        bytes32[] memory result = new bytes32[](count);
        uint256 index = 0;

        for (uint256 i = 0; i < allNodeIds.length; i++) {
            Node memory node = nodes[allNodeIds[i]];
            if (node.isActive && keccak256(bytes(node.location)) == keccak256(bytes(location))) {
                result[index] = allNodeIds[i];
                index++;
            }
        }

        return result;
    }

    /**
     * @dev Get node details
     */
    function getNode(bytes32 nodeId) external view returns (
        address owner,
        string memory location,
        uint256 bandwidthMbps,
        bool isActive,
        uint256 totalDataShared,
        uint256 totalEarnings,
        uint256 reputation
    ) {
        Node memory node = nodes[nodeId];
        return (
            node.owner,
            node.location,
            node.bandwidthMbps,
            node.isActive,
            node.totalDataShared,
            node.totalEarnings,
            node.reputation
        );
    }

    /**
     * @dev Get total number of nodes
     */
    function getTotalNodes() external view returns (uint256) {
        return allNodeIds.length;
    }
}

contracts/MinerNodeV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./AETHToken.sol";

/**
 * @title MinerNodeV2
 * @dev Enhanced Miner Node contract with levels, slashing, and progressive rewards
 */
contract MinerNodeV2 is Ownable {
    AETHToken public aethToken;
    address public nodeNFTContract;

    // Node levels with increasing benefits
    uint256 public constant MAX_LEVEL = 10;

    struct Node {
        address owner;
        string location;
        uint256 bandwidthMbps;
        uint256 registeredAt;
        bool isActive;
        uint256 totalDataShared; // in MB
        uint256 totalEarnings;
        uint256 reputation; // 0-100 score
        uint256 level; // 1-10
        uint256 experiencePoints; // XP for leveling up
        uint256 consecutiveUptimeDays;
        uint256 lastActiveTimestamp;
        uint256 totalDowntime; // in seconds
        uint256 slashedAmount; // Total amount slashed for violations
    }

    struct LevelRequirements {
        uint256 xpRequired;
        uint256 dataSharedGB;
        uint256 minUptime;
    }

    mapping(bytes32 => Node) public nodes;
    mapping(address => bytes32[]) public ownerNodes;
    mapping(uint256 => LevelRequirements) public levelRequirements;
    mapping(bytes32 => uint256) public nodeStake; // Required stake per node

    bytes32[] public allNodeIds;

    uint256 public constant MIN_BANDWIDTH = 10; // 10 Mbps
    uint256 public constant BASE_REWARD_PER_GB = 1 * 10**18; // 1 AETH per GB base
    uint256 public constant MIN_REPUTATION = 50;
    uint256 public constant REQUIRED_STAKE = 1000 * 10**18; // 1000 AETH stake
    uint256 public constant SLASH_AMOUNT = 100 * 10**18; // 100 AETH per violation
    uint256 public constant XP_PER_GB = 10; // 10 XP per GB shared

    // Commission for platform (basis points)
    uint256 public platformCommission = 500; // 5%
    address public platformFeeCollector;

    event NodeRegistered(bytes32 indexed nodeId, address indexed owner, string location);
    event NodeDeactivated(bytes32 indexed nodeId);
    event DataShared(bytes32 indexed nodeId, uint256 dataMB, uint256 reward, uint256 commission);
    event ReputationUpdated(bytes32 indexed nodeId, uint256 oldReputation, uint256 newReputation);
    event NodeLevelUp(bytes32 indexed nodeId, uint256 newLevel);
    event NodeSlashed(bytes32 indexed nodeId, uint256 amount, string reason);
    event StakeDeposited(bytes32 indexed nodeId, uint256 amount);
    event StakeWithdrawn(bytes32 indexed nodeId, uint256 amount);

    constructor(address _aethToken, address _feeCollector) Ownable(msg.sender) {
        aethToken = AETHToken(_aethToken);
        platformFeeCollector = _feeCollector;

        // Initialize level requirements
        levelRequirements[1] = LevelRequirements(0, 0, 0);
        levelRequirements[2] = LevelRequirements(100, 10, 90);
        levelRequirements[3] = LevelRequirements(300, 50, 95);
        levelRequirements[4] = LevelRequirements(600, 100, 97);
        levelRequirements[5] = LevelRequirements(1000, 250, 98);
        levelRequirements[6] = LevelRequirements(1500, 500, 99);
        levelRequirements[7] = LevelRequirements(2200, 1000, 99);
        levelRequirements[8] = LevelRequirements(3000, 2500, 99);
        levelRequirements[9] = LevelRequirements(4000, 5000, 99);
        levelRequirements[10] = LevelRequirements(5500, 10000, 100);
    }

    /**
     * @dev Register a new miner node with stake
     */
    function registerNode(string memory location, uint256 bandwidthMbps) external returns (bytes32) {
        require(bandwidthMbps >= MIN_BANDWIDTH, "Bandwidth too low");

        // Require stake deposit
        require(
            aethToken.transferFrom(msg.sender, address(this), REQUIRED_STAKE),
            "Stake transfer failed"
        );

        bytes32 nodeId = keccak256(abi.encodePacked(msg.sender, block.timestamp, allNodeIds.length));

        nodes[nodeId] = Node({
            owner: msg.sender,
            location: location,
            bandwidthMbps: bandwidthMbps,
            registeredAt: block.timestamp,
            isActive: true,
            totalDataShared: 0,
            totalEarnings: 0,
            reputation: 100,
            level: 1,
            experiencePoints: 0,
            consecutiveUptimeDays: 0,
            lastActiveTimestamp: block.timestamp,
            totalDowntime: 0,
            slashedAmount: 0
        });

        nodeStake[nodeId] = REQUIRED_STAKE;
        ownerNodes[msg.sender].push(nodeId);
        allNodeIds.push(nodeId);

        emit NodeRegistered(nodeId, msg.sender, location);
        emit StakeDeposited(nodeId, REQUIRED_STAKE);
        return nodeId;
    }

    /**
     * @dev Record data shared and distribute rewards with level multipliers
     */
    function recordDataShared(bytes32 nodeId, uint256 dataMB) external onlyOwner {
        require(nodes[nodeId].isActive, "Node not active");
        require(dataMB > 0, "Data must be > 0");

        Node storage node = nodes[nodeId];
        node.totalDataShared += dataMB;
        node.lastActiveTimestamp = block.timestamp;

        // Calculate base reward
        uint256 baseReward = (dataMB * BASE_REWARD_PER_GB) / 1000;

        // Apply level multiplier (10% per level)
        uint256 levelMultiplier = 100 + (node.level * 10);
        uint256 rewardWithLevel = (baseReward * levelMultiplier) / 100;

        // Apply NFT multiplier if exists
        if (nodeNFTContract != address(0)) {
            // This would call NodeNFT.getNodeMultiplier(nodeId)
            // For now, use base multiplier
        }

        // Calculate platform commission
        uint256 commission = (rewardWithLevel * platformCommission) / 10000;
        uint256 nodeReward = rewardWithLevel - commission;

        node.totalEarnings += nodeReward;

        // Add experience points
        uint256 xpGained = dataMB * XP_PER_GB / 1000;
        node.experiencePoints += xpGained;

        // Check for level up
        _checkLevelUp(nodeId);

        // Mint rewards
        aethToken.mint(node.owner, nodeReward);
        aethToken.mint(platformFeeCollector, commission);

        emit DataShared(nodeId, dataMB, nodeReward, commission);
    }

    /**
     * @dev Internal function to check and process level up
     */
    function _checkLevelUp(bytes32 nodeId) internal {
        Node storage node = nodes[nodeId];
        if (node.level >= MAX_LEVEL) return;

        uint256 nextLevel = node.level + 1;
        LevelRequirements memory req = levelRequirements[nextLevel];

        uint256 uptimePercent = calculateUptimePercent(nodeId);
        uint256 dataSharedGB = node.totalDataShared / 1000;

        if (
            node.experiencePoints >= req.xpRequired &&
            dataSharedGB >= req.dataSharedGB &&
            uptimePercent >= req.minUptime
        ) {
            node.level = nextLevel;
            emit NodeLevelUp(nodeId, nextLevel);
        }
    }

    /**
     * @dev Slash node for violations (downtime, fraud, etc.)
     */
    function slashNode(bytes32 nodeId, string memory reason) external onlyOwner {
        require(nodes[nodeId].isActive, "Node not active");
        require(nodeStake[nodeId] >= SLASH_AMOUNT, "Insufficient stake");

        Node storage node = nodes[nodeId];
        nodeStake[nodeId] -= SLASH_AMOUNT;
        node.slashedAmount += SLASH_AMOUNT;

        // Reduce reputation
        if (node.reputation >= 10) {
            uint256 oldReputation = node.reputation;
            node.reputation -= 10;
            emit ReputationUpdated(nodeId, oldReputation, node.reputation);
        }

        // Transfer slashed amount to platform
        require(aethToken.transfer(platformFeeCollector, SLASH_AMOUNT), "Slash transfer failed");

        emit NodeSlashed(nodeId, SLASH_AMOUNT, reason);

        // Deactivate if stake too low
        if (nodeStake[nodeId] < REQUIRED_STAKE / 2) {
            node.isActive = false;
            emit NodeDeactivated(nodeId);
        }
    }

    /**
     * @dev Deposit additional stake
     */
    function depositStake(bytes32 nodeId, uint256 amount) external {
        require(nodes[nodeId].owner == msg.sender, "Not node owner");
        require(amount > 0, "Amount must be > 0");

        require(aethToken.transferFrom(msg.sender, address(this), amount), "Transfer failed");
        nodeStake[nodeId] += amount;

        // Reactivate if was deactivated
        if (!nodes[nodeId].isActive && nodeStake[nodeId] >= REQUIRED_STAKE) {
            nodes[nodeId].isActive = true;
        }

        emit StakeDeposited(nodeId, amount);
    }

    /**
     * @dev Withdraw stake (only if node is deactivated)
     */
    function withdrawStake(bytes32 nodeId) external {
        require(nodes[nodeId].owner == msg.sender, "Not node owner");
        require(!nodes[nodeId].isActive, "Node still active");

        uint256 stake = nodeStake[nodeId];
        require(stake > 0, "No stake to withdraw");

        nodeStake[nodeId] = 0;
        require(aethToken.transfer(msg.sender, stake), "Transfer failed");

        emit StakeWithdrawn(nodeId, stake);
    }

    /**
     * @dev Update node reputation (only owner)
     */
    function updateReputation(bytes32 nodeId, uint256 newReputation) external onlyOwner {
        require(newReputation <= 100, "Reputation max 100");
        uint256 oldReputation = nodes[nodeId].reputation;
        nodes[nodeId].reputation = newReputation;
        emit ReputationUpdated(nodeId, oldReputation, newReputation);
    }

    /**
     * @dev Calculate uptime percentage
     */
    function calculateUptimePercent(bytes32 nodeId) public view returns (uint256) {
        Node memory node = nodes[nodeId];
        uint256 totalTime = block.timestamp - node.registeredAt;
        if (totalTime == 0) return 100;

        uint256 activeTime = totalTime - node.totalDowntime;
        return (activeTime * 100) / totalTime;
    }

    /**
     * @dev Deactivate node
     */
    function deactivateNode(bytes32 nodeId) external {
        require(nodes[nodeId].owner == msg.sender, "Not node owner");
        nodes[nodeId].isActive = false;
        emit NodeDeactivated(nodeId);
    }

    /**
     * @dev Get node basic info
     */
    function getNodeInfo(bytes32 nodeId) external view returns (
        address owner,
        string memory location,
        uint256 bandwidthMbps,
        bool isActive,
        uint256 totalDataShared,
        uint256 totalEarnings
    ) {
        Node memory node = nodes[nodeId];
        return (
            node.owner,
            node.location,
            node.bandwidthMbps,
            node.isActive,
            node.totalDataShared,
            node.totalEarnings
        );
    }

    /**
     * @dev Get node advanced stats
     */
    function getNodeStats(bytes32 nodeId) external view returns (
        uint256 reputation,
        uint256 level,
        uint256 experiencePoints,
        uint256 uptimePercent,
        uint256 stake
    ) {
        Node memory node = nodes[nodeId];
        return (
            node.reputation,
            node.level,
            node.experiencePoints,
            calculateUptimePercent(nodeId),
            nodeStake[nodeId]
        );
    }

    /**
     * @dev Get nodes by owner
     */
    function getNodesByOwner(address owner) external view returns (bytes32[] memory) {
        return ownerNodes[owner];
    }

    /**
     * @dev Get all node IDs
     */
    function getAllNodes() external view returns (bytes32[] memory) {
        return allNodeIds;
    }

    /**
     * @dev Get active nodes by reputation
     */
    function getActiveNodesByReputation(uint256 minReputation) external view returns (bytes32[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < allNodeIds.length; i++) {
            if (nodes[allNodeIds[i]].isActive && nodes[allNodeIds[i]].reputation >= minReputation) {
                count++;
            }
        }

        bytes32[] memory result = new bytes32[](count);
        uint256 index = 0;
        for (uint256 i = 0; i < allNodeIds.length; i++) {
            if (nodes[allNodeIds[i]].isActive && nodes[allNodeIds[i]].reputation >= minReputation) {
                result[index] = allNodeIds[i];
                index++;
            }
        }

        return result;
    }

    /**
     * @dev Set NFT contract address
     */
    function setNodeNFTContract(address _nodeNFT) external onlyOwner {
        nodeNFTContract = _nodeNFT;
    }

    /**
     * @dev Update platform commission
     */
    function setPlatformCommission(uint256 newCommission) external onlyOwner {
        require(newCommission <= 1000, "Commission too high"); // Max 10%
        platformCommission = newCommission;
    }

    /**
     * @dev Update fee collector
     */
    function setFeeCollector(address newCollector) external onlyOwner {
        platformFeeCollector = newCollector;
    }
}

contracts/NodeNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title NodeNFT
 * @dev NFT contract for elite miner nodes with enhanced earning multipliers
 */
contract NodeNFT is ERC721, ERC721URIStorage, Ownable {
    uint256 private _tokenIdCounter;

    // NFT Tiers with earning multipliers
    enum Tier { Bronze, Silver, Gold, Diamond, Legendary }

    struct NodeNFTInfo {
        Tier tier;
        uint256 earningMultiplier; // Multiplier in basis points (10000 = 1x, 15000 = 1.5x)
        uint256 mintedAt;
        uint256 lastUpgradeAt;
        bytes32 linkedNodeId; // Associated miner node ID
        bool isActive;
    }

    mapping(uint256 => NodeNFTInfo) public nftInfo;
    mapping(bytes32 => uint256) public nodeIdToNFT; // Link node ID to NFT token ID
    mapping(address => uint256[]) public userNFTs;

    // Tier requirements and multipliers
    mapping(Tier => uint256) public tierMultiplier;
    mapping(Tier => uint256) public tierRequiredUptime; // In days
    mapping(Tier => uint256) public tierRequiredData; // In GB

    // Marketplace
    struct Listing {
        uint256 price;
        address seller;
        bool isActive;
    }
    mapping(uint256 => Listing) public listings;

    uint256 public marketplaceFee = 250; // 2.5% fee in basis points
    address public feeCollector;

    event NFTMinted(address indexed to, uint256 indexed tokenId, Tier tier, bytes32 nodeId);
    event NFTUpgraded(uint256 indexed tokenId, Tier oldTier, Tier newTier);
    event NFTListed(uint256 indexed tokenId, uint256 price);
    event NFTSold(uint256 indexed tokenId, address indexed from, address indexed to, uint256 price);
    event NFTUnlisted(uint256 indexed tokenId);

    constructor(address _feeCollector) ERC721("Aetherium Node NFT", "ANFT") Ownable(msg.sender) {
        feeCollector = _feeCollector;

        // Initialize tier multipliers
        tierMultiplier[Tier.Bronze] = 11000; // 1.1x
        tierMultiplier[Tier.Silver] = 12500; // 1.25x
        tierMultiplier[Tier.Gold] = 15000; // 1.5x
        tierMultiplier[Tier.Diamond] = 20000; // 2x
        tierMultiplier[Tier.Legendary] = 30000; // 3x

        // Initialize tier requirements (uptime in days)
        tierRequiredUptime[Tier.Bronze] = 30;
        tierRequiredUptime[Tier.Silver] = 90;
        tierRequiredUptime[Tier.Gold] = 180;
        tierRequiredUptime[Tier.Diamond] = 365;
        tierRequiredUptime[Tier.Legendary] = 730;

        // Initialize tier requirements (data shared in GB)
        tierRequiredData[Tier.Bronze] = 100;
        tierRequiredData[Tier.Silver] = 500;
        tierRequiredData[Tier.Gold] = 2000;
        tierRequiredData[Tier.Diamond] = 10000;
        tierRequiredData[Tier.Legendary] = 50000;
    }

    /**
     * @dev Mint NFT for a qualified node (only owner/minter)
     */
    function mintNodeNFT(
        address to,
        bytes32 nodeId,
        Tier tier,
        string memory tokenURI
    ) external onlyOwner returns (uint256) {
        require(nodeIdToNFT[nodeId] == 0, "Node already has NFT");

        uint256 tokenId = _tokenIdCounter;
        _tokenIdCounter++;

        _safeMint(to, tokenId);
        _setTokenURI(tokenId, tokenURI);

        nftInfo[tokenId] = NodeNFTInfo({
            tier: tier,
            earningMultiplier: tierMultiplier[tier],
            mintedAt: block.timestamp,
            lastUpgradeAt: block.timestamp,
            linkedNodeId: nodeId,
            isActive: true
        });

        nodeIdToNFT[nodeId] = tokenId;
        userNFTs[to].push(tokenId);

        emit NFTMinted(to, tokenId, tier, nodeId);
        return tokenId;
    }

    /**
     * @dev Upgrade NFT tier based on node performance
     */
    function upgradeNFT(uint256 tokenId, Tier newTier) external onlyOwner {
        require(_ownerOf(tokenId) != address(0), "NFT does not exist");
        NodeNFTInfo storage info = nftInfo[tokenId];
        require(uint8(newTier) > uint8(info.tier), "Can only upgrade to higher tier");

        Tier oldTier = info.tier;
        info.tier = newTier;
        info.earningMultiplier = tierMultiplier[newTier];
        info.lastUpgradeAt = block.timestamp;

        emit NFTUpgraded(tokenId, oldTier, newTier);
    }

    /**
     * @dev List NFT for sale on marketplace
     */
    function listNFT(uint256 tokenId, uint256 price) external {
        require(ownerOf(tokenId) == msg.sender, "Not NFT owner");
        require(price > 0, "Price must be > 0");
        require(!listings[tokenId].isActive, "Already listed");

        listings[tokenId] = Listing({
            price: price,
            seller: msg.sender,
            isActive: true
        });

        emit NFTListed(tokenId, price);
    }

    /**
     * @dev Unlist NFT from marketplace
     */
    function unlistNFT(uint256 tokenId) external {
        require(listings[tokenId].seller == msg.sender, "Not seller");
        require(listings[tokenId].isActive, "Not listed");

        delete listings[tokenId];
        emit NFTUnlisted(tokenId);
    }

    /**
     * @dev Buy NFT from marketplace
     */
    function buyNFT(uint256 tokenId) external payable {
        Listing memory listing = listings[tokenId];
        require(listing.isActive, "NFT not for sale");
        require(msg.value >= listing.price, "Insufficient payment");

        address seller = listing.seller;
        uint256 price = listing.price;

        // Calculate fees
        uint256 fee = (price * marketplaceFee) / 10000;
        uint256 sellerAmount = price - fee;

        // Transfer NFT
        _transfer(seller, msg.sender, tokenId);

        // Transfer funds
        payable(seller).transfer(sellerAmount);
        payable(feeCollector).transfer(fee);

        // Remove listing
        delete listings[tokenId];

        // Update user NFT tracking
        _removeFromUserNFTs(seller, tokenId);
        userNFTs[msg.sender].push(tokenId);

        emit NFTSold(tokenId, seller, msg.sender, price);

        // Refund excess payment
        if (msg.value > price) {
            payable(msg.sender).transfer(msg.value - price);
        }
    }

    /**
     * @dev Get earning multiplier for a node
     */
    function getNodeMultiplier(bytes32 nodeId) external view returns (uint256) {
        uint256 tokenId = nodeIdToNFT[nodeId];
        if (tokenId == 0 || !nftInfo[tokenId].isActive) {
            return 10000; // 1x default multiplier
        }
        return nftInfo[tokenId].earningMultiplier;
    }

    /**
     * @dev Check if node is eligible for NFT upgrade
     */
    function checkUpgradeEligibility(
        bytes32 nodeId,
        uint256 uptimeDays,
        uint256 dataSharedGB
    ) external view returns (bool eligible, Tier nextTier) {
        uint256 tokenId = nodeIdToNFT[nodeId];
        if (tokenId == 0) return (false, Tier.Bronze);

        NodeNFTInfo memory info = nftInfo[tokenId];
        Tier currentTier = info.tier;

        // Can't upgrade Legendary
        if (currentTier == Tier.Legendary) return (false, Tier.Legendary);

        Tier next = Tier(uint8(currentTier) + 1);

        if (uptimeDays >= tierRequiredUptime[next] && dataSharedGB >= tierRequiredData[next]) {
            return (true, next);
        }

        return (false, next);
    }

    /**
     * @dev Get all NFTs owned by an address
     */
    function getUserNFTs(address user) external view returns (uint256[] memory) {
        return userNFTs[user];
    }

    /**
     * @dev Get NFT info
     */
    function getNFTInfo(uint256 tokenId) external view returns (
        Tier tier,
        uint256 earningMultiplier,
        uint256 mintedAt,
        uint256 lastUpgradeAt,
        bytes32 linkedNodeId,
        bool isActive,
        string memory uri
    ) {
        NodeNFTInfo memory info = nftInfo[tokenId];
        return (
            info.tier,
            info.earningMultiplier,
            info.mintedAt,
            info.lastUpgradeAt,
            info.linkedNodeId,
            info.isActive,
            tokenURI(tokenId)
        );
    }

    /**
     * @dev Get active marketplace listings
     */
    function getActiveListing(uint256 tokenId) external view returns (
        uint256 price,
        address seller,
        bool isActive
    ) {
        Listing memory listing = listings[tokenId];
        return (listing.price, listing.seller, listing.isActive);
    }

    /**
     * @dev Internal: Remove token from user's NFT array
     */
    function _removeFromUserNFTs(address user, uint256 tokenId) internal {
        uint256[] storage nfts = userNFTs[user];
        for (uint256 i = 0; i < nfts.length; i++) {
            if (nfts[i] == tokenId) {
                nfts[i] = nfts[nfts.length - 1];
                nfts.pop();
                break;
            }
        }
    }

    /**
     * @dev Update marketplace fee (owner only)
     */
    function setMarketplaceFee(uint256 newFee) external onlyOwner {
        require(newFee <= 1000, "Fee too high"); // Max 10%
        marketplaceFee = newFee;
    }

    /**
     * @dev Update fee collector (owner only)
     */
    function setFeeCollector(address newCollector) external onlyOwner {
        feeCollector = newCollector;
    }

    // Override required functions
    function tokenURI(uint256 tokenId) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, ERC721URIStorage) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/PremiumVPN.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

interface IAETHToken {
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function burn(uint256 amount) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
}

/**
 * @title PremiumVPN
 * @dev Manages Premium VPN subscriptions and VPN connection burn mechanism
 */
contract PremiumVPN is Ownable {
    IAETHToken public aethToken;

    // Premium subscription durations (in seconds)
    uint256 public constant MONTH = 30 days;
    uint256 public constant YEAR = 365 days;

    // Pricing
    uint256 public premiumMonthlyPrice = 1000 * 10**18;  // 1000 AETH
    uint256 public premiumYearlyPrice = 10000 * 10**18;  // 10000 AETH (discount)
    uint256 public burnAmountPerConnection = 10 * 10**18;  // 10 AETH per connection

    // Premium users
    struct PremiumInfo {
        bool isActive;
        uint256 expiryTime;
        uint256 subscribedAt;
        uint256 totalConnections;  // Track connections for stats
    }

    mapping(address => PremiumInfo) public premiumUsers;

    // Connection stats
    struct ConnectionStats {
        uint256 totalConnections;
        uint256 totalBurned;
        uint256 lastConnectionTime;
    }

    mapping(address => ConnectionStats) public userStats;

    // Global stats
    uint256 public totalBurnedGlobal;
    uint256 public totalConnectionsGlobal;
    uint256 public totalPremiumUsers;

    // Events
    event PremiumSubscribed(address indexed user, uint256 duration, uint256 amount, uint256 expiryTime);
    event PremiumRenewed(address indexed user, uint256 newExpiryTime);
    event PremiumExpired(address indexed user);
    event ConnectionBurned(address indexed user, uint256 amount);
    event PriceUpdated(string priceType, uint256 newPrice);

    constructor(address _aethToken) Ownable(msg.sender) {
        aethToken = IAETHToken(_aethToken);
    }

    /**
     * @dev Subscribe to Premium (monthly)
     */
    function subscribePremiumMonthly() external {
        _subscribePremium(MONTH, premiumMonthlyPrice);
    }

    /**
     * @dev Subscribe to Premium (yearly)
     */
    function subscribePremiumYearly() external {
        _subscribePremium(YEAR, premiumYearlyPrice);
    }

    /**
     * @dev Internal function to handle premium subscription
     */
    function _subscribePremium(uint256 duration, uint256 price) internal {
        require(price > 0, "Invalid price");

        PremiumInfo storage userPremium = premiumUsers[msg.sender];

        // Transfer tokens from user
        require(aethToken.transferFrom(msg.sender, address(this), price), "Transfer failed");

        // Burn 50% of subscription fee
        uint256 burnAmount = price / 2;
        aethToken.burn(burnAmount);
        totalBurnedGlobal += burnAmount;

        // Calculate new expiry time
        uint256 newExpiryTime;
        if (userPremium.isActive && userPremium.expiryTime > block.timestamp) {
            // Extend existing subscription
            newExpiryTime = userPremium.expiryTime + duration;
            emit PremiumRenewed(msg.sender, newExpiryTime);
        } else {
            // New subscription
            newExpiryTime = block.timestamp + duration;
            if (!userPremium.isActive) {
                totalPremiumUsers++;
            }
            emit PremiumSubscribed(msg.sender, duration, price, newExpiryTime);
        }

        userPremium.isActive = true;
        userPremium.expiryTime = newExpiryTime;
        userPremium.subscribedAt = block.timestamp;
    }

    /**
     * @dev Burn AETH tokens when user connects to VPN (called by backend)
     */
    function burnOnConnect(address user) external onlyOwner returns (bool) {
        // Check if user is premium
        PremiumInfo storage userPremium = premiumUsers[user];

        // Check if premium expired
        if (userPremium.isActive && userPremium.expiryTime <= block.timestamp) {
            userPremium.isActive = false;
            totalPremiumUsers--;
            emit PremiumExpired(user);
        }

        // Premium users don't need to burn
        if (userPremium.isActive && userPremium.expiryTime > block.timestamp) {
            userPremium.totalConnections++;
            userStats[user].totalConnections++;
            userStats[user].lastConnectionTime = block.timestamp;
            totalConnectionsGlobal++;
            return true;  // No burn for premium
        }

        // Non-premium users must burn tokens
        require(aethToken.transferFrom(user, address(this), burnAmountPerConnection), "Burn transfer failed");
        aethToken.burn(burnAmountPerConnection);

        // Update stats
        userStats[user].totalConnections++;
        userStats[user].totalBurned += burnAmountPerConnection;
        userStats[user].lastConnectionTime = block.timestamp;
        totalBurnedGlobal += burnAmountPerConnection;
        totalConnectionsGlobal++;

        emit ConnectionBurned(user, burnAmountPerConnection);
        return true;
    }

    /**
     * @dev Check if user is premium
     */
    function isPremium(address user) external view returns (bool) {
        PremiumInfo memory userPremium = premiumUsers[user];
        return userPremium.isActive && userPremium.expiryTime > block.timestamp;
    }

    /**
     * @dev Get premium info for user
     */
    function getPremiumInfo(address user) external view returns (
        bool isActive,
        uint256 expiryTime,
        uint256 subscribedAt,
        uint256 totalConnections,
        uint256 daysRemaining
    ) {
        PremiumInfo memory userPremium = premiumUsers[user];
        uint256 remaining = 0;

        if (userPremium.isActive && userPremium.expiryTime > block.timestamp) {
            remaining = (userPremium.expiryTime - block.timestamp) / 1 days;
        }

        return (
            userPremium.isActive && userPremium.expiryTime > block.timestamp,
            userPremium.expiryTime,
            userPremium.subscribedAt,
            userPremium.totalConnections,
            remaining
        );
    }

    /**
     * @dev Get user connection stats
     */
    function getUserStats(address user) external view returns (
        uint256 totalConnections,
        uint256 totalBurned,
        uint256 lastConnectionTime
    ) {
        ConnectionStats memory stats = userStats[user];
        return (stats.totalConnections, stats.totalBurned, stats.lastConnectionTime);
    }

    /**
     * @dev Get global stats
     */
    function getGlobalStats() external view returns (
        uint256 _totalBurnedGlobal,
        uint256 _totalConnectionsGlobal,
        uint256 _totalPremiumUsers
    ) {
        return (totalBurnedGlobal, totalConnectionsGlobal, totalPremiumUsers);
    }

    /**
     * @dev Update monthly premium price (only owner)
     */
    function updateMonthlyPrice(uint256 newPrice) external onlyOwner {
        premiumMonthlyPrice = newPrice;
        emit PriceUpdated("monthly", newPrice);
    }

    /**
     * @dev Update yearly premium price (only owner)
     */
    function updateYearlyPrice(uint256 newPrice) external onlyOwner {
        premiumYearlyPrice = newPrice;
        emit PriceUpdated("yearly", newPrice);
    }

    /**
     * @dev Update burn amount per connection (only owner)
     */
    function updateBurnAmount(uint256 newAmount) external onlyOwner {
        burnAmountPerConnection = newAmount;
        emit PriceUpdated("burnAmount", newAmount);
    }

    /**
     * @dev Withdraw remaining AETH (only owner, for treasury)
     */
    function withdrawTreasury(address to, uint256 amount) external onlyOwner {
        require(aethToken.transfer(to, amount), "Withdraw failed");
    }
}

